HEAD_BLOCK='<!-- TN40_UI_HEAD_START -->\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link href="https://fonts.googleapis.com/css2?family=Hind+Siliguri:wght@400;500;600;700&family=Inter:wght@400;500;600;700;800&family=Noto+Sans+JP:wght@400;500;600;700;800&display=swap" rel="stylesheet">\n<style id="tn40-premium-ui">\n:root{\n  --tn40-bg:#0B0F19;--tn40-bg-deep:#080B12;--tn40-bg-2:#0D1117;\n  --tn40-surface:rgba(255,255,255,.035);--tn40-line:rgba(255,255,255,.085);\n  --tn40-text:#F3F4F6;--tn40-muted:#9CA3AF;--tn40-faint:#6B7280;\n  --tn40-accent:#FF2E63;--tn40-accent-2:#FF5C83;--tn40-blue:#8EA6CF;\n  --tn40-gold:#F2BE63;--tn40-ease:cubic-bezier(.16,1,.3,1);\n  --tn40-glow:0 0 0 1px rgba(255,46,99,.07),0 18px 50px rgba(255,46,99,.10);\n  --bg:var(--tn40-bg)!important;--panel:var(--tn40-surface)!important;\n  --card:var(--tn40-surface)!important;--text:var(--tn40-text)!important;\n  --muted:var(--tn40-muted)!important;--faint:var(--tn40-faint)!important;\n  --border:var(--tn40-line)!important;--line:var(--tn40-line)!important;\n  --red:var(--tn40-accent)!important;--green:var(--tn40-accent)!important;\n  --blue:var(--tn40-blue)!important;--navy:var(--tn40-bg-2)!important;\n  --gold:var(--tn40-gold)!important;\n}\nhtml{color-scheme:dark;background:var(--tn40-bg);scroll-behavior:smooth;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased}\nbody{\n  margin:0;color:var(--tn40-text);overflow-x:hidden;\n  font-family:"Inter","Hind Siliguri","Noto Sans JP",system-ui,-apple-system,"Segoe UI",sans-serif;\n  background:\n    radial-gradient(circle at 12% -10%,rgba(255,46,99,.10),transparent 31rem),\n    radial-gradient(circle at 92% 12%,rgba(113,139,190,.08),transparent 30rem),\n    linear-gradient(180deg,var(--tn40-bg-deep),var(--tn40-bg));\n}\n:lang(bn),.font-bn{font-family:"Hind Siliguri","Noto Sans Bengali","Nirmala UI",sans-serif!important}\n:lang(ja),.font-jp,.kanji,.kana{font-family:"Noto Sans JP","Yu Gothic",Meiryo,sans-serif!important}\nbutton,input,select,textarea{font:inherit}\nbutton,a,input,select,textarea{-webkit-tap-highlight-color:transparent}\n::selection{background:var(--tn40-accent);color:white}\n\n.app{min-height:100dvh!important;background:transparent!important}\n.sidebar{\n  background:rgba(8,11,18,.78)!important;border-color:var(--tn40-line)!important;\n  backdrop-filter:blur(20px) saturate(135%);-webkit-backdrop-filter:blur(20px) saturate(135%)\n}\n.main{position:relative;isolation:isolate}\n.main:before{\n  content:"";position:fixed;inset:0;z-index:-2;pointer-events:none;\n  background-image:linear-gradient(rgba(255,255,255,.015) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.015) 1px,transparent 1px);\n  background-size:48px 48px;mask-image:linear-gradient(to bottom,black,transparent 88%)\n}\n.topbar{border-color:var(--tn40-line)!important}\nh1,h2,h3,h4,h5,h6{color:var(--tn40-text)!important;letter-spacing:-.025em}\np,.muted,.tiny,.micro,.vmeta{color:var(--tn40-muted)!important}\n.word,.kanji{color:#FAFAFB!important}\n\n.sidebar,.topbar,.hero,.card,.panel,.stat,.vitem,.srsbox,.dialogue,.reading,.reading-box,\n.grammar-card,.kanji-card,.kanjicard,.searchwrap,.stagecard,.mockq,.mockchoice,.resultbox,\n.toast,.dialog-card,.question,.match,.drop-zone,.bubble,.lessonhead,.controls{\n  background:var(--tn40-surface)!important;border:1px solid var(--tn40-line)!important;\n  box-shadow:inset 0 1px rgba(255,255,255,.025),0 14px 44px rgba(0,0,0,.16)!important;\n  backdrop-filter:blur(16px) saturate(135%);-webkit-backdrop-filter:blur(16px) saturate(135%)\n}\n.bubble,.turn:nth-child(even) .bubble{background:rgba(255,255,255,.035)!important}\n.turn:nth-child(even) .avatar{background:var(--tn40-accent)!important}\n.avatar{border:1px solid rgba(255,255,255,.10)!important}\n\n.hero,.panel,.dialogue,.reading,.reading-box,.dialog-card,.srsbox,.lessonhead{border-radius:16px!important}\n.card,.stat,.vitem,.question,.match,.drop-zone,.stagecard,.mockq,.mockchoice,.resultbox,\n.searchwrap,.bubble,.kanjicard,.kanji-card,.grammar-card{border-radius:14px!important}\n\n.brand,.nav button,.topbar button,.actions .btn,.btn,.listenbtn,.markbtn,.option,.mockchoice{\n  transition:transform .42s var(--tn40-ease),border-color .42s var(--tn40-ease),\n  background .42s var(--tn40-ease),color .42s var(--tn40-ease),box-shadow .42s var(--tn40-ease)!important\n}\n.nav button{border:1px solid transparent!important;color:#B7BEC9!important}\n.nav button:hover,.nav button.active{\n  color:white!important;border-color:rgba(255,46,99,.24)!important;\n  background:linear-gradient(135deg,rgba(255,46,99,.11),rgba(255,255,255,.025))!important;\n  box-shadow:0 10px 28px rgba(255,46,99,.07)!important\n}\n.nav button.active{box-shadow:inset 3px 0 var(--tn40-accent),0 10px 30px rgba(255,46,99,.08)!important}\n\ninput,select,textarea,.select,.search,.input{\n  min-height:44px;color:var(--tn40-text)!important;background:rgba(255,255,255,.035)!important;\n  border:1px solid var(--tn40-line)!important;border-radius:12px!important;outline:none;\n  transition:border-color .35s var(--tn40-ease),box-shadow .35s var(--tn40-ease),background .35s var(--tn40-ease)!important\n}\ninput::placeholder,textarea::placeholder{color:#69717E!important}\ninput:focus,select:focus,textarea:focus,.search:focus,.input:focus{\n  border-color:rgba(255,46,99,.48)!important;box-shadow:0 0 0 4px rgba(255,46,99,.08)!important\n}\n\n.btn,.listenbtn,.markbtn,.option,.pagination button,.actions button{\n  min-height:42px;border:1px solid var(--tn40-line)!important;border-radius:12px!important;\n  background:rgba(255,255,255,.035)!important;color:var(--tn40-text)!important\n}\n.btn:hover,.listenbtn:hover,.markbtn:hover,.option:hover,.pagination button:hover,\n.card:hover,.vitem:hover,.kanjicard:hover,.grammar-card:hover{\n  transform:translateY(-2px);border-color:rgba(255,46,99,.30)!important;box-shadow:var(--tn40-glow)!important\n}\n.btn.primary,.btn.active,.actions .btn:first-child{\n  background:linear-gradient(135deg,var(--tn40-accent),#C81D4A)!important;\n  border-color:rgba(255,255,255,.08)!important;color:white!important;\n  box-shadow:0 14px 36px rgba(255,46,99,.22)!important\n}\n.chip,.tag{border:1px solid var(--tn40-line)!important;background:rgba(255,255,255,.035)!important;color:#CBD1D9!important}\n.progress,.bar{background:rgba(255,255,255,.06)!important}\n.progress>*,.bar>*{background:linear-gradient(90deg,var(--tn40-accent),var(--tn40-accent-2))!important}\n\ndialog{color:var(--tn40-text);background:transparent!important;border:0!important;padding:0}\ndialog::backdrop{\n  background:rgba(2,5,11,.72);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);\n  animation:tn40-backdrop .32s ease both\n}\ndialog[open] .dialog-card,dialog[open]{animation:tn40-dialog .46s var(--tn40-ease) both}\n@keyframes tn40-dialog{from{opacity:0;transform:translateY(12px) scale(.95)}to{opacity:1;transform:none}}\n@keyframes tn40-backdrop{from{opacity:0}to{opacity:1}}\n.close{min-width:42px;min-height:42px;border-radius:12px!important}\n\n/* New namespaced hero */\n.tn40-hero{\n  position:relative;overflow:hidden;isolation:isolate;\n  display:grid;grid-template-columns:minmax(0,1.18fr) minmax(270px,.62fr);\n  gap:28px;align-items:center;margin:0 0 24px;padding:clamp(24px,4vw,52px);\n  border:1px solid rgba(255,255,255,.085);border-radius:18px;\n  background:radial-gradient(circle at 76% 22%,rgba(255,46,99,.16),transparent 28rem),\n             linear-gradient(135deg,rgba(255,255,255,.045),rgba(255,255,255,.018));\n  box-shadow:0 30px 100px rgba(0,0,0,.28),inset 0 1px rgba(255,255,255,.04);\n  backdrop-filter:blur(18px) saturate(140%);-webkit-backdrop-filter:blur(18px) saturate(140%)\n}\n.tn40-hero:before{\n  content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;\n  background:linear-gradient(110deg,transparent 0 55%,rgba(255,255,255,.025) 55% 56%,transparent 56%),\n             radial-gradient(circle at 82% 74%,rgba(142,166,207,.10),transparent 30%)\n}\n.tn40-hero:after{\n  content:"";position:absolute;right:-80px;top:-85px;width:280px;height:280px;border-radius:50%;\n  border:1px solid rgba(255,46,99,.17);\n  box-shadow:0 0 0 30px rgba(255,46,99,.025),0 0 0 70px rgba(255,46,99,.018);pointer-events:none\n}\n.tn40-badge{\n  width:max-content;max-width:100%;display:flex;align-items:center;gap:9px;padding:8px 11px;\n  border:1px solid rgba(255,46,99,.25);border-radius:999px;background:rgba(255,46,99,.065);\n  color:#FF88A5;font-size:11px;font-weight:700;letter-spacing:.04em\n}\n.tn40-badge i{width:7px;height:7px;border-radius:50%;background:var(--tn40-accent);box-shadow:0 0 0 5px rgba(255,46,99,.10),0 0 18px var(--tn40-accent)}\n.tn40-hero h1{\n  max-width:850px;margin:20px 0 0;color:#F9FAFB!important;\n  font-family:"Hind Siliguri","Inter",sans-serif!important;\n  font-size:clamp(38px,5vw,70px)!important;line-height:1.02!important;\n  font-weight:700!important;letter-spacing:-.045em!important;text-wrap:balance\n}\n.tn40-hero h1 span{\n  color:transparent;background:linear-gradient(110deg,#FFF,#FF8DA9 28%,#FF2E63 66%,#FF8DA9);\n  -webkit-background-clip:text;background-clip:text\n}\n.tn40-lead{\n  max-width:760px;margin:18px 0 0;color:#AEB6C1!important;\n  font-family:"Hind Siliguri","Inter",sans-serif!important;\n  font-size:clamp(15px,1.5vw,19px);line-height:1.72\n}\n.tn40-jp{margin:10px 0 0;color:#737E8E!important;font-family:"Noto Sans JP",sans-serif!important;font-size:13px;letter-spacing:.08em}\n.tn40-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:24px}\n.tn40-cta,.tn40-ghost{\n  min-height:48px;display:inline-flex;align-items:center;justify-content:center;gap:9px;padding:0 17px;\n  border-radius:13px;font-weight:700;cursor:pointer;\n  transition:transform .42s var(--tn40-ease),box-shadow .42s var(--tn40-ease),border-color .42s var(--tn40-ease)!important\n}\n.tn40-cta{border:1px solid rgba(255,255,255,.10);background:linear-gradient(135deg,var(--tn40-accent),#C91F4D);color:#fff;box-shadow:0 14px 40px rgba(255,46,99,.25)}\n.tn40-ghost{border:1px solid var(--tn40-line);background:rgba(255,255,255,.035);color:#D7DCE3}\n.tn40-cta:hover,.tn40-ghost:hover{transform:translateY(-2px);border-color:rgba(255,46,99,.35);box-shadow:0 18px 50px rgba(255,46,99,.18)}\n.tn40-cockpit{\n  position:relative;display:grid;gap:10px;padding:15px;border:1px solid rgba(255,255,255,.08);\n  border-radius:16px;background:rgba(3,6,12,.30)\n}\n.tn40-cockpit-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:4px 2px 9px}\n.tn40-cockpit-head span{color:#7C8796;font-size:10px;font-weight:700;letter-spacing:.12em}\n.tn40-cockpit-head b{display:flex;align-items:center;gap:6px;color:#79DBC9;font-size:10px}\n.tn40-cockpit-head b:before{content:"";width:7px;height:7px;border-radius:50%;background:#79DBC9;box-shadow:0 0 14px #79DBC9}\n.tn40-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}\n.tn40-metric{\n  min-height:104px;display:flex;flex-direction:column;justify-content:flex-end;padding:13px;\n  border:1px solid rgba(255,255,255,.07);border-radius:13px;background:rgba(255,255,255,.028)\n}\n.tn40-metric small{color:#727C89;font-size:9px;font-weight:700;letter-spacing:.08em}\n.tn40-metric strong{margin-top:8px;color:#F8FAFC;font-size:clamp(22px,2.5vw,34px);line-height:1}\n.tn40-metric em{margin-top:5px;color:#919AA7;font-style:normal;font-size:10px}\n.tn40-orbit{\n  position:relative;height:88px;overflow:hidden;border:1px solid rgba(255,255,255,.07);\n  border-radius:13px;background:radial-gradient(circle at 50% 115%,rgba(255,46,99,.20),transparent 45%),rgba(255,255,255,.02)\n}\n.tn40-orbit:before,.tn40-orbit:after{\n  content:"";position:absolute;left:50%;top:50%;width:200px;height:200px;\n  transform:translate(-50%,-13%);border:1px solid rgba(255,255,255,.08);border-radius:50%\n}\n.tn40-orbit:after{width:130px;height:130px;border-color:rgba(255,46,99,.22)}\n.tn40-orbit span{position:absolute;left:50%;top:50%;transform:translate(-50%,-40%);color:#E7EAF0;font-family:"Noto Sans JP",sans-serif;font-size:26px;letter-spacing:.22em}\n.tn40-note{display:flex;justify-content:space-between;gap:10px;color:#707B89;font-size:9px}\n.tn40-note b{color:#A6AFBA}\n\n@media(max-width:1000px){.tn40-hero{grid-template-columns:1fr}.tn40-cockpit{max-width:760px}}\n@media(max-width:900px){\n  .app{display:block!important}\n  .sidebar{\n    position:relative!important;top:auto!important;height:auto!important;min-height:0!important;width:100%!important;\n    border-right:0!important;border-bottom:1px solid var(--tn40-line)!important;padding-bottom:10px!important\n  }\n  .nav{display:flex!important;gap:7px!important;overflow-x:auto!important;overscroll-behavior-inline:contain;scrollbar-width:none;padding-bottom:4px}\n  .nav::-webkit-scrollbar{display:none}.nav button{flex:0 0 auto!important;min-height:44px!important;white-space:nowrap}\n  .main{padding:18px 16px 92px!important}\n  .topbar{\n    position:sticky;top:0;z-index:20;margin-inline:-16px;padding-inline:16px!important;\n    background:rgba(8,11,18,.84)!important;backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px)\n  }\n}\n@media(max-width:680px){\n  body{font-size:15px}.main{padding:12px 12px 92px!important}.topbar{margin-inline:-12px;padding-inline:12px!important}\n  .tn40-hero{margin-bottom:14px;padding:19px;border-radius:16px}\n  .tn40-hero h1{margin-top:16px;font-size:clamp(34px,11vw,49px)!important;line-height:1.04!important}\n  .tn40-lead{font-size:15px;line-height:1.7}\n  .tn40-actions{display:grid;grid-template-columns:1fr}.tn40-cta,.tn40-ghost{width:100%;min-height:50px}\n  .tn40-metrics{grid-template-columns:1fr 1fr}.tn40-metric:first-child{grid-column:1/-1}.tn40-metric{min-height:86px}\n  .stats,.grid,.two{grid-template-columns:1fr!important}.controls,.actions,.pagination{flex-wrap:wrap!important}\n  button,.btn,.listenbtn,.markbtn,.option,input,select,textarea{min-height:44px!important}\n  input,select,textarea{font-size:16px!important}\n  .vitem,.card,.panel,.dialogue,.reading,.srsbox,.lessonhead{padding:14px!important}\n  .turn{grid-template-columns:36px minmax(0,1fr)!important;gap:8px!important}.avatar{width:36px!important;height:36px!important}\n  dialog .dialog-card{width:min(100% - 18px,720px)!important;max-height:88dvh;overflow:auto}\n}\n@media(max-width:420px){\n  .tn40-badge{font-size:9px}.tn40-metrics{grid-template-columns:1fr}.tn40-metric:first-child{grid-column:auto}.tn40-note{display:grid}\n}\n@media(prefers-reduced-motion:reduce){\n  html{scroll-behavior:auto}\n  *,*::before,*::after{animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important}\n}\n</style>\n<!-- TN40_UI_HEAD_END -->'
BODY_BLOCK='<!-- TN40_UI_BODY_START -->\n<script>\n(function TN40PremiumHero(){\n  "use strict";\n  function mount(){\n    if(document.querySelector(".tn40-hero")) return;\n    var main=document.querySelector(".main");\n    if(!main) return;\n\n    var hero=document.createElement("section");\n    hero.className="tn40-hero";\n    hero.setAttribute("aria-label","Welcome to The Nihongo Vibes");\n    hero.innerHTML=\n      \'<div class="tn40-copy">\'+\n        \'<div class="tn40-badge"><i></i><span>Top Notch v40 · Learning Intelligence</span></div>\'+\n        \'<h1 lang="bn">সহজে ও সাবলীল উপায়ে <span>N5 জাপানিজ</span> শিখুন</h1>\'+\n        \'<p class="tn40-lead" lang="bn">ভোকাবুলারি, listening, shadowing, conversation, grammar, reading ও kanji—একটি connected learning flow-তে প্রতিদিন অল্প অল্প করে শিখুন।</p>\'+\n        \'<p class="tn40-jp" lang="ja">毎日、少しずつ。自然に身につく。</p>\'+\n        \'<div class="tn40-actions">\'+\n          \'<button type="button" class="tn40-cta">আজকের শেখা শুরু করুন <span aria-hidden="true">→</span></button>\'+\n          \'<button type="button" class="tn40-ghost">N5 · 学習スタジオ</button>\'+\n        \'</div>\'+\n      \'</div>\'+\n      \'<aside class="tn40-cockpit" aria-label="Learning overview">\'+\n        \'<div class="tn40-cockpit-head"><span>LEARNING INTELLIGENCE</span><b>ONLINE</b></div>\'+\n        \'<div class="tn40-metrics">\'+\n          \'<div class="tn40-metric"><small>VOCABULARY</small><strong>১,০১১+</strong><em lang="bn">শব্দ</em></div>\'+\n          \'<div class="tn40-metric"><small>LESSONS</small><strong>২৫</strong><em>JLPT N5</em></div>\'+\n          \'<div class="tn40-metric"><small>TARGET</small><strong>N5</strong><em>Connected Study</em></div>\'+\n        \'</div>\'+\n        \'<div class="tn40-orbit" aria-hidden="true"><span>日本語</span></div>\'+\n        \'<div class="tn40-note"><span><b>বাংলা</b> explanation</span><span><b>日本語</b> immersion</span><span><b>English</b> UI</span></div>\'+\n      \'</aside>\';\n\n    var topbar=main.querySelector(".topbar");\n    if(topbar && topbar.parentNode===main) topbar.insertAdjacentElement("afterend",hero);\n    else main.insertBefore(hero,main.firstChild);\n\n    var cta=hero.querySelector(".tn40-cta");\n    if(cta) cta.addEventListener("click",function(){\n      var all=main.querySelectorAll(".hero,.lessonhead,.panel,.card,.vlist,.srsbox");\n      var target=null;\n      for(var i=0;i<all.length;i++){\n        if(!all[i].classList.contains("tn40-hero")){target=all[i];break}\n      }\n      if(target&&target.scrollIntoView) target.scrollIntoView({behavior:"smooth",block:"start"});\n    });\n\n    var ghost=hero.querySelector(".tn40-ghost");\n    if(ghost) ghost.addEventListener("click",function(){\n      var target=main.querySelector(".stats,.lessonhead,.panel,.grid");\n      if(target&&target.scrollIntoView) target.scrollIntoView({behavior:"smooth",block:"start"});\n    });\n  }\n  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",mount,{once:true});\n  else mount();\n})();\n</script>\n<!-- TN40_UI_BODY_END -->'

def strip_block(text,start,end):
    return re.sub(re.escape(start)+r".*?"+re.escape(end)+r"\s*","",text,flags=re.S|re.I)

def clean(text):
    return strip_block(strip_block(text,HEAD_START,HEAD_END),BODY_START,BODY_END)

def insert_before(text,tag,block):
    pos=text.lower().rfind(tag.lower())
    if pos<0: raise RuntimeError("Missing closing tag: "+tag)
    return text[:pos]+"\n"+block+"\n"+text[pos:]

def ids(text):
    return set(re.findall(r'\bid\s*=\s*["\']([^"\']+)["\']',text,flags=re.I))

def sha(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()

def main():
    ap=argparse.ArgumentParser(description="Safe additive Top Notch v40 UI upgrade")
    ap.add_argument("source",nargs="?",default="docs/legacy-root/index-v44-single-file.html")
    ap.add_argument("output",nargs="?",default="index.html")
    a=ap.parse_args()
    src=Path(a.source); dst=Path(a.output)
    if not src.exists():
        raise SystemExit("SOURCE NOT FOUND: "+str(src)+"\nRun from repo root or pass your existing index.html path.")
    raw=src.read_text(encoding="utf-8")
    original=clean(raw)
    before_ids=ids(original)
    critical=["speechSynthesis","localStorage","addEventListener","querySelector","getElementById"]
    before_counts={t:original.count(t) for t in critical}

    upgraded=insert_before(original,"</head>",HEAD_BLOCK)
    upgraded=insert_before(upgraded,"</body>",BODY_BLOCK)
    restored=clean(upgraded)

    if restored!=original: raise SystemExit("SAFE PATCH FAILED: original content changed.")
    if ids(restored)!=before_ids: raise SystemExit("SAFE PATCH FAILED: original ID set changed.")
    after_counts={t:restored.count(t) for t in critical}
    if before_counts!=after_counts: raise SystemExit("SAFE PATCH FAILED: critical JS token counts changed.")

    dst.parent.mkdir(parents=True,exist_ok=True)
    if src.resolve()==dst.resolve():
        backup=src.with_name(src.stem+".pre-tn40-backup"+src.suffix)
        if not backup.exists(): shutil.copy2(src,backup)
    dst.write_text(upgraded,encoding="utf-8")

    print("TOP NOTCH v40 SAFE PATCH PASS")
    print("Source:",src)
    print("Output:",dst)
    print("Original SHA256:",sha(original))
    print("Restored SHA256:",sha(restored))
    print("Preserved IDs:",len(before_ids))
    for k,v in before_counts.items(): print(k+":",v)
    print("Original application is exactly recoverable by removing TN40 marker blocks.")

if __name__=="__main__":
    main()
